@Injectable()
export class MaintenanceControlService {
  constructor(@Inject(DB_TOKEN.amo) private readonly db: ModuleDb, private readonly authz: AuthzService, private readonly audit: AuditService, private readonly personnel: PersonnelQuery) {}
  private resource(p: Principal, id='*') { return { kind: 'maintenance_control' as const, id, attr: { operatorId: p.operatorId } }; }
  private async can(p: Principal, action: string, id='*') { return this.authz.check(p, this.resource(p,id), action); }
  private async next(seq: string, prefix: string) { const r=await this.db.db.execute<{n:string}>(sql.raw(`select nextval('amo.${seq}')::text n`)); return `${prefix}-${r.rows[0].n}`; }
  private async auditRecord(p: Principal, action: string, entityType: string, entityId: string, data: unknown) { await this.audit.record(this.db,'amo',{operatorId:p.operatorId,actor:actorOf(p),action,entityType,entityId,data:data as Record<string,unknown>}); }

  async dashboard(p: Principal, stationFilter?: string) {
    await this.can(p,'read');
    const o=p.operatorId; const sw=stationFilter?.toUpperCase();
    const wo=await this.db.db.select().from(workOrders).where(sw?and(eq(workOrders.operatorId,o),eq(workOrders.station,sw)):eq(workOrders.operatorId,o)).orderBy(desc(workOrders.updatedAt)).limit(100);
    const visits=await this.db.db.select().from(lineVisits).where(sw?and(eq(lineVisits.operatorId,o),eq(lineVisits.station,sw)):eq(lineVisits.operatorId,o)).orderBy(asc(lineVisits.scheduledIn)).limit(100);
    const aog=await this.db.db.select().from(aogCases).where(and(eq(aogCases.operatorId,o),inArray(aogCases.status,['OPEN','DIAGNOSIS','MATERIAL','RECOVERY','RTS']))).orderBy(asc(aogCases.recoveryEta));
    const openHandover=await this.db.db.select().from(handovers).where(and(eq(handovers.operatorId,o),eq(handovers.status,'OPEN'))).orderBy(desc(handovers.handedOverAt)).limit(20);
    const dueTools=await this.db.db.select().from(toolAssets).where(and(eq(toolAssets.operatorId,o),inArray(toolAssets.status,['AVAILABLE','ISSUED','OUT_FOR_CALIBRATION','QUARANTINE','LOST','DAMAGED']))).orderBy(asc(toolAssets.calibratedUntil)).limit(100);
    const shops=await this.db.db.select().from(shopOrders).where(and(eq(shopOrders.operatorId,o),sql`${shopOrders.status} <> 'RELEASED'`)).orderBy(asc(shopOrders.plannedRelease)).limit(50);
    return { workOrders:wo,lineVisits:visits,aog,openHandovers:openHandover,tools:dueTools,shopOrders:shops,
      counts:{workOrdersOpen:wo.filter(x=>!['COMPLETE','CANCELLED'].includes(x.status)).length,lineVisitsActive:visits.filter(x=>!['DEPARTED','CANCELLED'].includes(x.status)).length,aogOpen:aog.length,handoversOpen:openHandover.length,toolsUnavailable:dueTools.filter(x=>x.status!=='AVAILABLE').length,shopOpen:shops.length} };
  }

  async capabilities(p:Principal, stationFilter?:string){await this.can(p,'read');return this.db.db.select().from(stationCapabilities).where(stationFilter?and(eq(stationCapabilities.operatorId,p.operatorId),eq(stationCapabilities.station,stationFilter.toUpperCase())):eq(stationCapabilities.operatorId,p.operatorId)).orderBy(asc(stationCapabilities.station),asc(stationCapabilities.aircraftType));}
  async createCapability(p:Principal,b:z.infer<typeof capabilitySchema>){await this.can(p,'manage_station');const from=new Date(`${b.effectiveFrom}T00:00:00Z`),until=b.effectiveUntil?new Date(`${b.effectiveUntil}T00:00:00Z`):null;if(until&&until<from)throw new DomainError('CAPABILITY_DATES','Effective-until precedes effective-from',422);const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.insert(stationCapabilities).values({id,operatorId:p.operatorId,station:b.station,aircraftType:b.aircraftType.toUpperCase(),maintenanceLevel:b.maintenanceLevel,scope:b.scope,limitations:b.limitations,authorityRef:b.authorityRef,effectiveFrom:from,effectiveUntil:until,active:true,minimumAuthorizedStaff:b.minimumAuthorizedStaff,requiredToolNos:b.requiredToolNos.map(x=>x.toUpperCase()),facilities:b.facilities,approvedBy:actorOf(p),approvedAt:new Date(),createdAt:new Date()});await this.auditRecord(p,'maintenance.capability_approved','maintenance_station_capability',id,b)});return {id};}
  async capabilityState(p:Principal,id:string,b:z.infer<typeof capabilityStateSchema>){await this.can(p,'manage_station',id);const [row]=await this.db.db.select().from(stationCapabilities).where(and(eq(stationCapabilities.id,id),eq(stationCapabilities.operatorId,p.operatorId)));if(!row)throw new DomainError('CAPABILITY_NOT_FOUND','Station capability not found',404);await this.db.transaction(async()=>{await this.db.db.update(stationCapabilities).set({active:b.active}).where(eq(stationCapabilities.id,id));await this.auditRecord(p,b.active?'maintenance.capability_activated':'maintenance.capability_suspended','maintenance_station_capability',id,{reason:b.reason})});return {ok:true};}
  private async requireCapability(p:Principal,wo:typeof workOrders.$inferSelect){
    if(!wo.aircraftType)return;
    const level=wo.orderType==='BASE'?'BASE':wo.orderType==='AOG'?'AOG':wo.orderType==='ENGINE'?'ENGINE_CHANGE':wo.orderType==='COMPONENT'?'SHOP_SUPPORT':'LINE';
    const now=new Date();
    const rows=await this.db.db.select().from(stationCapabilities).where(and(eq(stationCapabilities.operatorId,p.operatorId),eq(stationCapabilities.station,wo.station),eq(stationCapabilities.aircraftType,wo.aircraftType),eq(stationCapabilities.maintenanceLevel,level),eq(stationCapabilities.active,true)));
    const cap=rows.find(r=>r.effectiveFrom<=now&&(!r.effectiveUntil||r.effectiveUntil>=now));
    if(!cap)throw new DomainError('STATION_CAPABILITY','No effective approved station capability for this work order',422);
    const staff=await this.personnel.maintenancePersonnel(p.operatorId,wo.station,wo.aircraftType);
    if(staff.filter(x=>x.authorised).length<cap.minimumAuthorizedStaff)throw new DomainError('STATION_STAFFING',`Station capability requires ${cap.minimumAuthorizedStaff} currently authorised staff; ${staff.filter(x=>x.authorised).length} available`,422);
    if(cap.requiredToolNos.length){
      const tools=await this.db.db.select().from(toolAssets).where(and(eq(toolAssets.operatorId,p.operatorId),eq(toolAssets.station,wo.station),inArray(toolAssets.toolNo,cap.requiredToolNos)));
      const valid=new Set(tools.filter(t=>!['QUARANTINE','LOST','DAMAGED','RETIRED','OUT_FOR_CALIBRATION'].includes(t.status)&&(!t.calibrationRequired||!!t.calibratedUntil&&t.calibratedUntil>=now)).map(t=>t.toolNo));
      const missing=cap.requiredToolNos.filter(x=>!valid.has(x));
      if(missing.length)throw new DomainError('STATION_TOOLS',`Station capability missing serviceable required tools: ${missing.join(', ')}`,422);
    }
  }

  async workOrderList(p:Principal,stationFilter?:string){await this.can(p,'read');return this.db.db.select().from(workOrders).where(stationFilter?and(eq(workOrders.operatorId,p.operatorId),eq(workOrders.station,stationFilter.toUpperCase())):eq(workOrders.operatorId,p.operatorId)).orderBy(desc(workOrders.updatedAt)).limit(500);}
  async createWorkOrder(p:Principal,b:z.infer<typeof workOrderSchema>){
    await this.can(p,'plan'); const id=await this.next('work_order_seq','WO');
    const ps=b.plannedStart?new Date(b.plannedStart):null, pe=b.plannedEnd?new Date(b.plannedEnd):null;
    if(ps&&pe&&pe<=ps)throw new DomainError('WORK_ORDER_WINDOW','Planned end must be after planned start',422);
    let slaDueAt:Date|null=null;
    if(b.contractId){
      const r=await this.db.db.execute<{id:string;customer_ref:string;station_scope:string[];aircraft_types:string[];maintenance_levels:string[];tat_sla_hours:number|null;effective_from:Date;effective_until:Date|null;active:boolean}>(sql`select id,customer_ref,station_scope,aircraft_types,maintenance_levels,tat_sla_hours,effective_from,effective_until,active from amo.maintenance_contracts where id=${b.contractId} and operator_id=${p.operatorId}`);
      const c=r.rows[0]; if(!c||!c.active)throw new DomainError('MAINT_CONTRACT','Maintenance contract is not active',422);
      const now=new Date(); if(c.effective_from>now||(c.effective_until&&c.effective_until<now))throw new DomainError('MAINT_CONTRACT_DATES','Maintenance contract is not effective',422);
      if(b.customerRef&&c.customer_ref!==b.customerRef)throw new DomainError('MAINT_CONTRACT_CUSTOMER','Work-order customer does not match contract',422);
      if(c.station_scope.length&&!c.station_scope.includes(b.station))throw new DomainError('MAINT_CONTRACT_STATION','Contract does not cover this station',422);
      if(b.aircraftType&&c.aircraft_types.length&&!c.aircraft_types.includes(b.aircraftType.toUpperCase()))throw new DomainError('MAINT_CONTRACT_TYPE','Contract does not cover this aircraft type',422);
      const level=b.orderType==='BASE'?'BASE':b.orderType==='AOG'?'AOG':b.orderType==='ENGINE'?'ENGINE_CHANGE':b.orderType==='COMPONENT'?'SHOP_SUPPORT':'LINE';
      if(c.maintenance_levels.length&&!c.maintenance_levels.includes(level))throw new DomainError('MAINT_CONTRACT_LEVEL','Contract does not cover this maintenance level',422);
      if(c.tat_sla_hours)slaDueAt=new Date((ps??now).getTime()+c.tat_sla_hours*3600000);
    }
    await this.db.transaction(async()=>{await this.db.db.insert(workOrders).values({id,operatorId:p.operatorId,orderType:b.orderType,tail:b.tail,componentRef:b.componentRef,station:b.station,aircraftType:b.aircraftType?.toUpperCase()??null,title:b.title,priority:b.priority,customerRef:b.customerRef,sourceType:b.sourceType,sourceId:b.sourceId,plannedStart:ps,plannedEnd:pe,actualStart:null,actualEnd:null,status:'DRAFT',holdReason:null,plannedHours:b.plannedHours,actualMinutes:0,taskCardIds:b.taskCardIds,contractId:b.contractId,slaDueAt,customerApprovalRef:b.customerApprovalRef,createdBy:actorOf(p),createdAt:new Date(),updatedAt:new Date()});await this.auditRecord(p,'maintenance.work_order_created','work_order',id,{...b,slaDueAt})});return {id};
  }
  async workOrderState(p:Principal,id:string,b:z.infer<typeof workOrderStateSchema>){await this.can(p,b.state==='COMPLETE'?'supervise':'plan',id);const [wo]=await this.db.db.select().from(workOrders).where(and(eq(workOrders.id,id),eq(workOrders.operatorId,p.operatorId)));if(!wo)throw new DomainError('WORK_ORDER_NOT_FOUND',`Work order ${id} not found`,404);if(!transitionAllowed(WORK_ORDER_TRANSITIONS,wo.status as any,b.state as any))throw new DomainError('WORK_ORDER_TRANSITION',`${wo.status} cannot transition to ${b.state}`,409);if(['RELEASED','IN_PROGRESS'].includes(b.state))await this.requireCapability(p,wo);if(b.state==='HOLD'&&!b.reason)throw new DomainError('HOLD_REASON','Hold requires a reason',422);if(b.state==='COMPLETE'){
      const issued=await this.db.db.select({id:toolMovements.id}).from(toolMovements).where(and(eq(toolMovements.operatorId,p.operatorId),eq(toolMovements.workOrderId,id),eq(toolMovements.movement,'ISSUE')));const returned=await this.db.db.select({id:toolMovements.id}).from(toolMovements).where(and(eq(toolMovements.operatorId,p.operatorId),eq(toolMovements.workOrderId,id),eq(toolMovements.movement,'RETURN')));if(issued.length>returned.length)throw new DomainError('TOOLS_OUT','Work order has tools not returned to the crib',422);
      const out=await this.db.db.execute(sql`select id from amo.outsourced_work where operator_id=${p.operatorId} and work_order_id=${id} and status not in ('ACCEPTED','CANCELLED') limit 1`);if(out.rows.length)throw new DomainError('OUTSOURCE_OPEN','Outsourced work has not been accepted',422);const kit=await this.db.db.execute(sql`select id from amo.material_kits where operator_id=${p.operatorId} and work_order_id=${id} and status not in ('ISSUED','CLOSED','CANCELLED') limit 1`);if(kit.rows.length)throw new DomainError('MATERIAL_KIT_OPEN','Material kit is not ready/issued for work-order completion',422);
      if(wo.plannedHours>0){const ass=await this.db.db.execute<{n:number}>(sql`select count(*)::int n from amo.work_order_assignments where operator_id=${p.operatorId} and work_order_id=${id}`);if((ass.rows[0]?.n??0)===0)throw new DomainError('WORKFORCE_UNASSIGNED','Work order has planned labour but no assigned personnel',422);}
    }
    const now=new Date();await this.db.transaction(async()=>{await this.db.db.update(workOrders).set({status:b.state,holdReason:b.state==='HOLD'?b.reason:null,actualStart:b.state==='IN_PROGRESS'?(wo.actualStart??now):wo.actualStart,actualEnd:b.state==='COMPLETE'?now:wo.actualEnd,updatedAt:now}).where(eq(workOrders.id,id));await this.auditRecord(p,'maintenance.work_order_state','work_order',id,{from:wo.status,to:b.state,reason:b.reason})});return {ok:true};}

  async lineVisitList(p:Principal,stationFilter?:string){await this.can(p,'read');return this.db.db.select().from(lineVisits).where(stationFilter?and(eq(lineVisits.operatorId,p.operatorId),eq(lineVisits.station,stationFilter.toUpperCase())):eq(lineVisits.operatorId,p.operatorId)).orderBy(asc(lineVisits.scheduledIn)).limit(500);}
  async createLineVisit(p:Principal,b:z.infer<typeof lineVisitSchema>){await this.can(p,'line_control');const si=new Date(b.scheduledIn),so=new Date(b.scheduledOut);if(so<=si)throw new DomainError('VISIT_WINDOW','Scheduled out must be after scheduled in',422);if(b.workOrderId){const [wo]=await this.db.db.select().from(workOrders).where(and(eq(workOrders.id,b.workOrderId),eq(workOrders.operatorId,p.operatorId)));if(!wo)throw new DomainError('WORK_ORDER_NOT_FOUND','Linked work order not found',404);}const id=await this.next('line_visit_seq','LV');await this.db.transaction(async()=>{await this.db.db.insert(lineVisits).values({id,operatorId:p.operatorId,tail:b.tail.toUpperCase(),aircraftType:b.aircraftType.toUpperCase(),station:b.station,inboundFlight:b.inboundFlight,outboundFlight:b.outboundFlight,scheduledIn:si,scheduledOut:so,actualIn:null,actualOut:null,status:'PLANNED',workOrderId:b.workOrderId,openDefects:b.openDefects,deferredDefectRefs:b.deferredDefectRefs,turnaroundNotes:b.turnaroundNotes,createdBy:actorOf(p),createdAt:new Date(),updatedAt:new Date()});await this.auditRecord(p,'maintenance.line_visit_created','line_visit',id,b)});return {id};}
  async lineVisitState(p:Principal,id:string,b:z.infer<typeof lineStateSchema>){
    await this.can(p,'line_control',id); const [v]=await this.db.db.select().from(lineVisits).where(and(eq(lineVisits.id,id),eq(lineVisits.operatorId,p.operatorId)));
    if(!v)throw new DomainError('LINE_VISIT_NOT_FOUND','Line visit not found',404);
    if(!transitionAllowed(LINE_VISIT_TRANSITIONS,v.status as any,b.state as any))throw new DomainError('LINE_VISIT_TRANSITION',`${v.status} cannot transition to ${b.state}`,409);
    const openDefects=b.openDefects??v.openDefects; const deferred=b.deferredDefectRefs??v.deferredDefectRefs;
    if(b.state==='RELEASED'){
      if(openDefects>0)throw new DomainError('OPEN_DEFECTS','Open defects must be cleared or formally deferred before maintenance release',422);
      if(deferred.some(x=>!x.trim()))throw new DomainError('DEFERRED_DEFECT_REF','Deferred defect references must be traceable',422);
      if(v.workOrderId){const [wo]=await this.db.db.select().from(workOrders).where(and(eq(workOrders.id,v.workOrderId),eq(workOrders.operatorId,p.operatorId)));if(wo&&wo.status!=='COMPLETE')throw new DomainError('WORK_ORDER_OPEN','Linked work order is not complete',422);}
    }
    const now=new Date(); await this.db.transaction(async()=>{await this.db.db.update(lineVisits).set({status:b.state,actualIn:b.state==='ARRIVED'?(v.actualIn??now):v.actualIn,actualOut:b.state==='DEPARTED'?now:v.actualOut,openDefects,deferredDefectRefs:deferred,turnaroundNotes:b.note??v.turnaroundNotes,updatedAt:now}).where(eq(lineVisits.id,id));await this.auditRecord(p,'maintenance.line_visit_state','line_visit',id,{from:v.status,to:b.state,note:b.note,openDefects,deferredDefectRefs:deferred})});return {ok:true};
  }

  async handoverList(p:Principal,stationFilter?:string){await this.can(p,'read');const hs=await this.db.db.select().from(handovers).where(stationFilter?and(eq(handovers.operatorId,p.operatorId),eq(handovers.station,stationFilter.toUpperCase())):eq(handovers.operatorId,p.operatorId)).orderBy(desc(handovers.handedOverAt)).limit(100);const ids=hs.map(x=>x.id);const items=ids.length?await this.db.db.select().from(handoverItems).where(and(eq(handoverItems.operatorId,p.operatorId),inArray(handoverItems.handoverId,ids))):[];return hs.map(h=>({...h,items:items.filter(i=>i.handoverId===h.id)}));}
  async createHandover(p:Principal,b:z.infer<typeof handoverSchema>){await this.can(p,'handover');const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.insert(handovers).values({id,operatorId:p.operatorId,station:b.station,workArea:b.workArea,outgoingShift:b.outgoingShift,incomingShift:b.incomingShift,handedOverBy:actorOf(p),handedOverAt:new Date(),acceptedBy:null,acceptedAt:null,status:'OPEN',summary:b.summary});for(const i of b.items)await this.db.db.insert(handoverItems).values({id:randomUUID(),operatorId:p.operatorId,handoverId:id,itemType:i.itemType,reference:i.reference,description:i.description,priority:i.priority,status:'OPEN',resolvedBy:null,resolvedAt:null,resolution:null});await this.auditRecord(p,'maintenance.handover_created','shift_handover',id,{...b,itemCount:b.items.length})});return {id};}
  async acceptHandover(p:Principal,id:string){await this.can(p,'handover',id);const [h]=await this.db.db.select().from(handovers).where(and(eq(handovers.id,id),eq(handovers.operatorId,p.operatorId)));if(!h)throw new DomainError('HANDOVER_NOT_FOUND','Handover not found',404);if(h.status!=='OPEN')throw new DomainError('HANDOVER_ACCEPTED','Handover is already accepted',409);if(h.handedOverBy===actorOf(p))throw new DomainError('INDEPENDENT_HANDOVER','Incoming acceptance must be by a different person',422);await this.db.transaction(async()=>{await this.db.db.update(handovers).set({status:'ACCEPTED',acceptedBy:actorOf(p),acceptedAt:new Date()}).where(eq(handovers.id,id));await this.auditRecord(p,'maintenance.handover_accepted','shift_handover',id,{outgoing:h.handedOverBy,incoming:actorOf(p)})});return {ok:true};}
  async resolveHandoverItem(p:Principal,hid:string,itemId:string,b:z.infer<typeof resolveItemSchema>){await this.can(p,'handover',hid);const [item]=await this.db.db.select().from(handoverItems).where(and(eq(handoverItems.id,itemId),eq(handoverItems.handoverId,hid),eq(handoverItems.operatorId,p.operatorId)));if(!item)throw new DomainError('HANDOVER_ITEM_NOT_FOUND','Handover item not found',404);await this.db.transaction(async()=>{await this.db.db.update(handoverItems).set({status:'RESOLVED',resolvedBy:actorOf(p),resolvedAt:new Date(),resolution:b.resolution}).where(eq(handoverItems.id,itemId));await this.auditRecord(p,'maintenance.handover_item_resolved','handover_item',itemId,{handoverId:hid,resolution:b.resolution})});return {ok:true};}

  async toolList(p:Principal,stationFilter?:string){await this.can(p,'read');return this.db.db.select().from(toolAssets).where(stationFilter?and(eq(toolAssets.operatorId,p.operatorId),eq(toolAssets.station,stationFilter.toUpperCase())):eq(toolAssets.operatorId,p.operatorId)).orderBy(asc(toolAssets.toolNo));}
  async createTool(p:Principal,b:z.infer<typeof toolSchema>){await this.can(p,'tool_control');if(b.calibrationRequired&&(!b.calibratedUntil||!b.certificateRef))throw new DomainError('CALIBRATION_EVIDENCE','Calibrated tools require due date and certificate reference',422);const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.insert(toolAssets).values({id,operatorId:p.operatorId,toolNo:b.toolNo.toUpperCase(),serial:b.serial,description:b.description,station:b.station,crib:b.crib,kitCode:b.kitCode,calibrationRequired:b.calibrationRequired,calibratedUntil:b.calibratedUntil?new Date(`${b.calibratedUntil}T00:00:00Z`):null,certificateRef:b.certificateRef,status:'AVAILABLE',conditionNote:null,updatedAt:new Date()});await this.auditRecord(p,'maintenance.tool_registered','tool_asset',id,b)});return {id};}
  async moveTool(p:Principal,id:string,b:z.infer<typeof toolMoveSchema>){await this.can(p,'tool_control',id);const [t]=await this.db.db.select().from(toolAssets).where(and(eq(toolAssets.id,id),eq(toolAssets.operatorId,p.operatorId)));if(!t)throw new DomainError('TOOL_NOT_FOUND','Tool not found',404);const today=new Date();if(b.movement==='ISSUE'){if(t.status!=='AVAILABLE')throw new DomainError('TOOL_UNAVAILABLE',`Tool is ${t.status}`,409);if(t.calibrationRequired&&(!t.calibratedUntil||t.calibratedUntil<today))throw new DomainError('TOOL_CALIBRATION_EXPIRED','Tool calibration is expired',422);if(!b.workOrderId&&!b.taskCardId)throw new DomainError('TOOL_ISSUE_TARGET','Issue requires work order or task card',422);}const next:Record<string,string>={ISSUE:'ISSUED',RETURN:'AVAILABLE',SEND_CALIBRATION:'OUT_FOR_CALIBRATION',RETURN_CALIBRATION:'AVAILABLE',QUARANTINE:'QUARANTINE',MARK_LOST:'LOST',MARK_DAMAGED:'DAMAGED',RETIRE:'RETIRED'};if(b.movement==='RETURN'&&t.status!=='ISSUED')throw new DomainError('TOOL_RETURN_STATE','Only an issued tool can be returned',409);if(b.movement==='RETURN_CALIBRATION'&&(!b.calibratedUntil||!b.certificateRef))throw new DomainError('CALIBRATION_EVIDENCE','Calibration return requires new due date and certificate reference',422);await this.db.transaction(async()=>{await this.db.db.insert(toolMovements).values({id:randomUUID(),operatorId:p.operatorId,toolId:id,movement:b.movement,workOrderId:b.workOrderId,taskCardId:b.taskCardId,personnelId:b.personnelId,reference:b.reference,note:b.note,actor:actorOf(p),occurredAt:new Date()});await this.db.db.update(toolAssets).set({status:next[b.movement],calibratedUntil:b.movement==='RETURN_CALIBRATION'&&b.calibratedUntil?new Date(`${b.calibratedUntil}T00:00:00Z`):t.calibratedUntil,certificateRef:b.movement==='RETURN_CALIBRATION'?(b.certificateRef??t.certificateRef):t.certificateRef,conditionNote:b.note??t.conditionNote,updatedAt:new Date()}).where(eq(toolAssets.id,id));if(b.movement==='ISSUE')await this.db.db.execute(sql`update amo.tool_reservations set status='ISSUED' where operator_id=${p.operatorId} and tool_id=${id} and status='RESERVED' and (${b.workOrderId} is null or work_order_id=${b.workOrderId}) and (${b.taskCardId} is null or task_card_id=${b.taskCardId})`);if(b.movement==='RETURN')await this.db.db.execute(sql`update amo.tool_reservations set status='FULFILLED' where operator_id=${p.operatorId} and tool_id=${id} and status='ISSUED'`);await this.auditRecord(p,'maintenance.tool_movement','tool_asset',id,b)});return {ok:true};}

  async shopList(p:Principal){await this.can(p,'read');const orders=await this.db.db.select().from(shopOrders).where(eq(shopOrders.operatorId,p.operatorId)).orderBy(desc(shopOrders.updatedAt)).limit(300);const ids=orders.map(o=>o.id);const findings=ids.length?await this.db.db.select().from(shopFindings).where(and(eq(shopFindings.operatorId,p.operatorId),inArray(shopFindings.shopOrderId,ids))):[];return orders.map(o=>({...o,findings:findings.filter(f=>f.shopOrderId===o.id)}));}
  async createShop(p:Principal,b:z.infer<typeof shopSchema>){await this.can(p,'shop_control');const id=await this.next('shop_order_seq','SO');await this.db.transaction(async()=>{await this.db.db.insert(shopOrders).values({id,operatorId:p.operatorId,shopType:b.shopType,partNo:b.partNo.toUpperCase(),serial:b.serial,customerRef:b.customerRef,incomingCondition:b.incomingCondition,workscope:b.workscope,status:'INDUCTED',inductionRef:b.inductionRef,releaseCertificateRef:null,testResult:null,plannedRelease:b.plannedRelease?new Date(`${b.plannedRelease}T00:00:00Z`):null,actualRelease:null,createdBy:actorOf(p),createdAt:new Date(),updatedAt:new Date()});await this.auditRecord(p,'maintenance.shop_order_inducted','shop_order',id,b)});return {id};}
  async shopState(p:Principal,id:string,b:z.infer<typeof shopStateSchema>){await this.can(p,'shop_control',id);const [o]=await this.db.db.select().from(shopOrders).where(and(eq(shopOrders.id,id),eq(shopOrders.operatorId,p.operatorId)));if(!o)throw new DomainError('SHOP_ORDER_NOT_FOUND','Shop order not found',404);if(!transitionAllowed(SHOP_ORDER_TRANSITIONS,o.status as any,b.state as any))throw new DomainError('SHOP_TRANSITION',`${o.status} cannot transition to ${b.state}`,409);if(b.state==='READY_FOR_RELEASE'&&!b.testResult&&!o.testResult)throw new DomainError('SHOP_TEST_REQUIRED','Passing test result is required before release readiness',422);if(b.state==='RELEASED'&&!b.releaseCertificateRef)throw new DomainError('SHOP_RELEASE_CERT','Release certificate reference is required',422);const open=await this.db.db.select().from(shopFindings).where(and(eq(shopFindings.operatorId,p.operatorId),eq(shopFindings.shopOrderId,id),inArray(shopFindings.status,['OPEN','APPROVED','REPAIRED'])));if(b.state==='RELEASED'&&open.length)throw new DomainError('SHOP_FINDINGS_OPEN','All shop findings must be closed before release',422);if(b.state==='RELEASED'){const pp=await this.db.db.execute(sql`select id from amo.shop_piece_parts where operator_id=${p.operatorId} and shop_order_id=${id} and disposition in ('HOLD','REPAIR','EXTERNAL_REPAIR') limit 1`);if(pp.rows.length)throw new DomainError('SHOP_PIECE_PARTS_OPEN','All held/repair piece-parts must be dispositioned before release',422);}await this.db.transaction(async()=>{await this.db.db.update(shopOrders).set({status:b.state,testResult:b.testResult??o.testResult,releaseCertificateRef:b.releaseCertificateRef??o.releaseCertificateRef,actualRelease:b.state==='RELEASED'?new Date():o.actualRelease,updatedAt:new Date()}).where(eq(shopOrders.id,id));await this.auditRecord(p,'maintenance.shop_order_state','shop_order',id,{from:o.status,to:b.state,reason:b.reason,testResult:b.testResult,releaseCertificateRef:b.releaseCertificateRef})});return {ok:true};}
  async addFinding(p:Principal,id:string,b:z.infer<typeof findingSchema>){await this.can(p,'shop_control',id);const [o]=await this.db.db.select().from(shopOrders).where(and(eq(shopOrders.id,id),eq(shopOrders.operatorId,p.operatorId)));if(!o)throw new DomainError('SHOP_ORDER_NOT_FOUND','Shop order not found',404);const fid=randomUUID();await this.db.transaction(async()=>{await this.db.db.insert(shopFindings).values({id:fid,operatorId:p.operatorId,shopOrderId:id,finding:b.finding,disposition:b.disposition,partNo:b.partNo,serial:b.serial,repairRef:b.repairRef,status:'OPEN',createdBy:actorOf(p),createdAt:new Date(),closedBy:null,closedAt:null});await this.auditRecord(p,'maintenance.shop_finding_created','shop_finding',fid,{shopOrderId:id,...b})});return {id:fid};}
  async findingState(p:Principal,id:string,fid:string,b:z.infer<typeof findingStateSchema>){await this.can(p,'shop_control',id);const [f]=await this.db.db.select().from(shopFindings).where(and(eq(shopFindings.id,fid),eq(shopFindings.shopOrderId,id),eq(shopFindings.operatorId,p.operatorId)));if(!f)throw new DomainError('SHOP_FINDING_NOT_FOUND','Shop finding not found',404);await this.db.transaction(async()=>{await this.db.db.update(shopFindings).set({status:b.state,disposition:b.disposition??f.disposition,repairRef:b.repairRef??f.repairRef,closedBy:b.state==='CLOSED'?actorOf(p):f.closedBy,closedAt:b.state==='CLOSED'?new Date():f.closedAt}).where(eq(shopFindings.id,fid));await this.auditRecord(p,'maintenance.shop_finding_state','shop_finding',fid,{from:f.status,to:b.state,disposition:b.disposition,repairRef:b.repairRef})});return {ok:true};}

  async executionList(p:Principal,cardId:string){await this.can(p,'execute',cardId);return this.db.db.select().from(executionRecords).where(and(eq(executionRecords.operatorId,p.operatorId),eq(executionRecords.taskCardId,cardId))).orderBy(asc(executionRecords.stepNo),asc(executionRecords.recordedAt));}
  async recordExecution(p:Principal,cardId:string,b:z.infer<typeof executionSchema>){await this.can(p,'execute',cardId);const card=await this.db.db.execute<{status:string;steps:unknown[]}>(sql`select status, steps from amo.task_cards where id=${cardId} and operator_id=${p.operatorId}`);if(!card.rows[0])throw new DomainError('TASK_CARD_NOT_FOUND','Task card not found',404);if(card.rows[0].status==='CERTIFIED')throw new DomainError('CARD_CERTIFIED','Certified cards are immutable',409);const steps=card.rows[0].steps as Array<{n:number}>;if(!steps.some(x=>x.n===b.stepNo))throw new DomainError('STEP_UNKNOWN','Task-card step does not exist',422);let result:string|null=null;if(b.recordType==='MEASUREMENT'&&b.valueNumber!==null){result=measurementResult(b.valueNumber,b.lowerLimit,b.upperLimit);}
    const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.insert(executionRecords).values({id,operatorId:p.operatorId,taskCardId:cardId,stepNo:b.stepNo,recordType:b.recordType,valueText:b.valueText,valueNumber:b.valueNumber,unit:b.unit,lowerLimit:b.lowerLimit,upperLimit:b.upperLimit,result,reference:b.reference,recordedBy:actorOf(p),recordedAt:new Date(),inspectedBy:null,inspectedAt:null,inspectionSignature:null});await this.auditRecord(p,'maintenance.task_execution_recorded','task_execution_record',id,{taskCardId:cardId,...b,result})});return {id,result};}
  async inspectExecution(p:Principal,cardId:string,id:string,b:z.infer<typeof inspectionSchema>){await this.can(p,'inspect',cardId);const [r]=await this.db.db.select().from(executionRecords).where(and(eq(executionRecords.id,id),eq(executionRecords.taskCardId,cardId),eq(executionRecords.operatorId,p.operatorId)));if(!r)throw new DomainError('EXECUTION_RECORD_NOT_FOUND','Execution record not found',404);if(r.recordedBy===actorOf(p))throw new DomainError('INDEPENDENT_INSPECTION','Independent inspection must be by another person',422);if(r.inspectedBy)throw new DomainError('ALREADY_INSPECTED','Execution record already inspected',409);await this.db.transaction(async()=>{await this.db.db.update(executionRecords).set({result:b.result,reference:b.reference,inspectedBy:actorOf(p),inspectedAt:new Date(),inspectionSignature:b.signature??{note:b.note}}).where(eq(executionRecords.id,id));await this.auditRecord(p,'maintenance.task_execution_inspected','task_execution_record',id,{taskCardId:cardId,result:b.result,reference:b.reference,note:b.note})});return {ok:true};}

  async aogList(p:Principal){await this.can(p,'read');const cases=await this.db.db.select().from(aogCases).where(eq(aogCases.operatorId,p.operatorId)).orderBy(asc(aogCases.recoveryEta),desc(aogCases.openedAt)).limit(200);const ids=cases.map(c=>c.id);const updates=ids.length?await this.db.db.select().from(aogUpdates).where(and(eq(aogUpdates.operatorId,p.operatorId),inArray(aogUpdates.caseId,ids))).orderBy(desc(aogUpdates.createdAt)):[];return cases.map(c=>({...c,updates:updates.filter(u=>u.caseId===c.id)}));}
  async createAog(p:Principal,b:z.infer<typeof aogSchema>){await this.can(p,'aog_control');const id=await this.next('aog_case_seq','AOG');if(b.workOrderId){const [wo]=await this.db.db.select().from(workOrders).where(and(eq(workOrders.id,b.workOrderId),eq(workOrders.operatorId,p.operatorId)));if(!wo)throw new DomainError('WORK_ORDER_NOT_FOUND','Linked work order not found',404);}await this.db.transaction(async()=>{await this.db.db.insert(aogCases).values({id,operatorId:p.operatorId,tail:b.tail.toUpperCase(),station:b.station,defectRef:b.defectRef,workOrderId:b.workOrderId,severity:b.severity,status:'OPEN',technicalSummary:b.technicalSummary,recoveryEta:b.recoveryEta?new Date(b.recoveryEta):null,requiredPart:b.requiredPart,logisticsRef:b.logisticsRef,operationalImpact:b.operationalImpact,estimatedCostMinor:b.estimatedCostMinor,currency:b.currency,openedBy:actorOf(p),openedAt:new Date(),closedBy:null,closedAt:null});await this.auditRecord(p,'maintenance.aog_opened','aog_case',id,b)});return {id};}
  async updateAog(p:Principal,id:string,b:z.infer<typeof aogUpdateSchema>){
    await this.can(p,'aog_control',id); const [c]=await this.db.db.select().from(aogCases).where(and(eq(aogCases.id,id),eq(aogCases.operatorId,p.operatorId)));
    if(!c)throw new DomainError('AOG_NOT_FOUND','AOG case not found',404); if(c.status==='CLOSED')throw new DomainError('AOG_CLOSED','AOG case is closed',409); if(b.status==='CLOSED'&&c.status!=='RTS')throw new DomainError('AOG_RTS_REQUIRED','AOG case must reach RTS before closure',422);
    const uid=randomUUID(); await this.db.transaction(async()=>{await this.db.db.insert(aogUpdates).values({id:uid,operatorId:p.operatorId,caseId:id,updateType:b.updateType,note:b.note,recoveryEta:b.recoveryEta?new Date(b.recoveryEta):null,actor:actorOf(p),createdAt:new Date()});await this.db.db.update(aogCases).set({status:b.status??c.status,recoveryEta:b.recoveryEta?new Date(b.recoveryEta):c.recoveryEta,requiredPart:b.requiredPart===undefined?c.requiredPart:b.requiredPart,logisticsRef:b.logisticsRef===undefined?c.logisticsRef:b.logisticsRef,estimatedCostMinor:b.estimatedCostMinor??c.estimatedCostMinor,currency:b.currency??c.currency,closedBy:b.status==='CLOSED'?actorOf(p):c.closedBy,closedAt:b.status==='CLOSED'?new Date():c.closedAt}).where(eq(aogCases.id,id));await this.auditRecord(p,'maintenance.aog_updated','aog_case',id,b)});return {ok:true};
  }

  async maintenancePersonnel(p:Principal,stationCode:string,aircraftType?:string){await this.can(p,'read');return this.personnel.maintenancePersonnel(p.operatorId,stationCode.toUpperCase(),aircraftType?.toUpperCase());}

  async assignmentList(p:Principal,workOrderId:string){await this.can(p,'read',workOrderId);const r=await this.db.db.execute<Record<string,unknown>>(sql`select id,work_order_id as "workOrderId",personnel_id as "personnelId",assignment_role as "assignmentRole",trade,shift_ref as "shiftRef",planned_minutes as "plannedMinutes",actual_minutes as "actualMinutes",assigned_by as "assignedBy",assigned_at as "assignedAt",released_at as "releasedAt" from amo.work_order_assignments where operator_id=${p.operatorId} and work_order_id=${workOrderId} order by released_at nulls first, assignment_role, assigned_at`);return r.rows;}
  async assignWorkOrder(p:Principal,workOrderId:string,b:z.infer<typeof assignmentSchema>){await this.can(p,'supervise',workOrderId);const [wo]=await this.db.db.select().from(workOrders).where(and(eq(workOrders.id,workOrderId),eq(workOrders.operatorId,p.operatorId)));if(!wo)throw new DomainError('WORK_ORDER_NOT_FOUND','Work order not found',404);const person=await this.personnel.maintenancePerson(p.operatorId,b.personnelId);if(!person)throw new DomainError('PERSON_NOT_FOUND','Active maintenance personnel record not found',404);if(person.base&&person.base.toUpperCase()!==wo.station&&b.assignmentRole!=='SPECIALIST')throw new DomainError('PERSON_STATION',`Personnel base ${person.base} does not match work-order station ${wo.station}`,422);const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.execute(sql`insert into amo.work_order_assignments(id,operator_id,work_order_id,personnel_id,assignment_role,trade,shift_ref,planned_minutes,actual_minutes,assigned_by,assigned_at) values(${id},${p.operatorId},${workOrderId},${b.personnelId},${b.assignmentRole},${b.trade},${b.shiftRef},${b.plannedMinutes},0,${actorOf(p)},now()) on conflict(operator_id,work_order_id,personnel_id,assignment_role) do update set trade=excluded.trade,shift_ref=excluded.shift_ref,planned_minutes=excluded.planned_minutes,released_at=null`);await this.auditRecord(p,'maintenance.work_order_assignment','work_order_assignment',id,{workOrderId,...b})});return {id};}
  async assignmentTime(p:Principal,workOrderId:string,id:string,b:z.infer<typeof assignmentTimeSchema>){await this.can(p,'supervise',workOrderId);const r=await this.db.db.execute<{personnel_id:string}>(sql`update amo.work_order_assignments set actual_minutes=${b.actualMinutes} where id=${id} and operator_id=${p.operatorId} and work_order_id=${workOrderId} returning personnel_id`);if(!r.rows[0])throw new DomainError('ASSIGNMENT_NOT_FOUND','Work-order assignment not found',404);const sum=await this.db.db.execute<{total:number}>(sql`select coalesce(sum(actual_minutes),0)::int total from amo.work_order_assignments where operator_id=${p.operatorId} and work_order_id=${workOrderId}`);await this.db.db.update(workOrders).set({actualMinutes:sum.rows[0]?.total??0,updatedAt:new Date()}).where(and(eq(workOrders.id,workOrderId),eq(workOrders.operatorId,p.operatorId)));await this.auditRecord(p,'maintenance.labour_booked','work_order_assignment',id,{workOrderId,actualMinutes:b.actualMinutes});return {ok:true};}
  async releaseAssignment(p:Principal,workOrderId:string,id:string){await this.can(p,'supervise',workOrderId);const r=await this.db.db.execute(sql`update amo.work_order_assignments set released_at=now() where id=${id} and operator_id=${p.operatorId} and work_order_id=${workOrderId} and released_at is null returning id`);if(!r.rows[0])throw new DomainError('ASSIGNMENT_NOT_FOUND','Active assignment not found',404);await this.auditRecord(p,'maintenance.assignment_released','work_order_assignment',id,{workOrderId});return {ok:true};}

  async toolReservations(p:Principal,toolId?:string){await this.can(p,'read');const r=toolId?await this.db.db.execute<Record<string,unknown>>(sql`select id,tool_id as "toolId",work_order_id as "workOrderId",task_card_id as "taskCardId",reserved_from as "reservedFrom",reserved_until as "reservedUntil",status,reserved_by as "reservedBy",created_at as "createdAt" from amo.tool_reservations where operator_id=${p.operatorId} and tool_id=${toolId} order by reserved_from desc`):await this.db.db.execute<Record<string,unknown>>(sql`select id,tool_id as "toolId",work_order_id as "workOrderId",task_card_id as "taskCardId",reserved_from as "reservedFrom",reserved_until as "reservedUntil",status,reserved_by as "reservedBy",created_at as "createdAt" from amo.tool_reservations where operator_id=${p.operatorId} and status in ('RESERVED','ISSUED') order by reserved_from`);return r.rows;}
  async reserveTool(p:Principal,toolId:string,b:z.infer<typeof toolReservationSchema>){await this.can(p,'tool_control',toolId);const from=new Date(b.reservedFrom),until=new Date(b.reservedUntil);if(until<=from)throw new DomainError('TOOL_RESERVATION_WINDOW','Reservation end must be after start',422);const [t]=await this.db.db.select().from(toolAssets).where(and(eq(toolAssets.id,toolId),eq(toolAssets.operatorId,p.operatorId)));if(!t)throw new DomainError('TOOL_NOT_FOUND','Tool not found',404);if(['LOST','DAMAGED','RETIRED','QUARANTINE'].includes(t.status))throw new DomainError('TOOL_UNSERVICEABLE',`Tool is ${t.status}`,422);const overlap=await this.db.db.execute(sql`select id from amo.tool_reservations where operator_id=${p.operatorId} and tool_id=${toolId} and status in ('RESERVED','ISSUED') and reserved_from<${until} and reserved_until>${from} limit 1`);if(overlap.rows.length)throw new DomainError('TOOL_RESERVED','Tool already has an overlapping reservation',409);const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.execute(sql`insert into amo.tool_reservations(id,operator_id,tool_id,work_order_id,task_card_id,reserved_from,reserved_until,status,reserved_by) values(${id},${p.operatorId},${toolId},${b.workOrderId},${b.taskCardId},${from},${until},'RESERVED',${actorOf(p)})`);await this.auditRecord(p,'maintenance.tool_reserved','tool_reservation',id,{toolId,...b})});return {id};}
  async cancelToolReservation(p:Principal,id:string){await this.can(p,'tool_control',id);const r=await this.db.db.execute(sql`update amo.tool_reservations set status='CANCELLED' where id=${id} and operator_id=${p.operatorId} and status='RESERVED' returning tool_id`);if(!r.rows[0])throw new DomainError('TOOL_RESERVATION','Active reservation not found',404);await this.auditRecord(p,'maintenance.tool_reservation_cancelled','tool_reservation',id,{});return {ok:true};}

  async pieceParts(p:Principal,shopOrderId:string){await this.can(p,'read',shopOrderId);const r=await this.db.db.execute<Record<string,unknown>>(sql`select id,shop_order_id as "shopOrderId",part_no as "partNo",serial,lot_no as "lotNo",description,incoming_condition as "incomingCondition",disposition,repair_scheme_ref as "repairSchemeRef",external_order_ref as "externalOrderRef",trace_ref as "traceRef",installed,created_at as "createdAt",updated_at as "updatedAt" from amo.shop_piece_parts where operator_id=${p.operatorId} and shop_order_id=${shopOrderId} order by created_at`);return r.rows;}
  async addPiecePart(p:Principal,shopOrderId:string,b:z.infer<typeof piecePartSchema>){await this.can(p,'shop_control',shopOrderId);const [o]=await this.db.db.select().from(shopOrders).where(and(eq(shopOrders.id,shopOrderId),eq(shopOrders.operatorId,p.operatorId)));if(!o)throw new DomainError('SHOP_ORDER_NOT_FOUND','Shop order not found',404);const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.execute(sql`insert into amo.shop_piece_parts(id,operator_id,shop_order_id,part_no,serial,lot_no,description,incoming_condition,disposition,repair_scheme_ref,external_order_ref,trace_ref,created_by) values(${id},${p.operatorId},${shopOrderId},${b.partNo.toUpperCase()},${b.serial},${b.lotNo},${b.description},${b.incomingCondition},${b.disposition},${b.repairSchemeRef},${b.externalOrderRef},${b.traceRef},${actorOf(p)})`);await this.auditRecord(p,'maintenance.shop_piece_part_added','shop_piece_part',id,{shopOrderId,...b})});return {id};}
  async piecePartState(p:Principal,shopOrderId:string,id:string,b:z.infer<typeof piecePartStateSchema>){await this.can(p,'shop_control',shopOrderId);if(b.installed&&!piecePartMayInstall(b.disposition))throw new DomainError('PIECE_PART_INSTALL','Only serviceable/replacement piece-parts can be installed',422);const r=await this.db.db.execute(sql`update amo.shop_piece_parts set disposition=${b.disposition},repair_scheme_ref=coalesce(${b.repairSchemeRef??null},repair_scheme_ref),external_order_ref=coalesce(${b.externalOrderRef??null},external_order_ref),trace_ref=coalesce(${b.traceRef??null},trace_ref),installed=${b.installed},updated_at=now() where id=${id} and operator_id=${p.operatorId} and shop_order_id=${shopOrderId} returning id`);if(!r.rows[0])throw new DomainError('PIECE_PART_NOT_FOUND','Shop piece-part not found',404);await this.auditRecord(p,'maintenance.shop_piece_part_state','shop_piece_part',id,{shopOrderId,...b});return {ok:true};}

  async outsourced(p:Principal,workOrderId?:string,wpId?:string){await this.can(p,'read');let r;if(workOrderId)r=await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.outsourced_work where operator_id=${p.operatorId} and work_order_id=${workOrderId} order by created_at desc`);else if(wpId)r=await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.outsourced_work where operator_id=${p.operatorId} and wp_id=${wpId} order by created_at desc`);else r=await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.outsourced_work where operator_id=${p.operatorId} and status not in ('ACCEPTED','CANCELLED') order by due_at nulls last`);return r.rows;}
  async addOutsourced(p:Principal,b:z.infer<typeof outsourceSchema>){await this.can(p,'supervise');const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.execute(sql`insert into amo.outsourced_work(id,operator_id,work_order_id,wp_id,vendor_ref,scope,purchase_order_ref,outbound_ref,due_at,status,created_by) values(${id},${p.operatorId},${b.workOrderId},${b.wpId},${b.vendorRef},${b.scope},${b.purchaseOrderRef},${b.outboundRef},${b.dueAt?new Date(b.dueAt):null},'PLANNED',${actorOf(p)})`);await this.auditRecord(p,'maintenance.outsource_created','outsourced_work',id,b)});return {id};}
  async outsourcedState(p:Principal,id:string,b:z.infer<typeof outsourceStateSchema>){await this.can(p,'supervise',id);const q=await this.db.db.execute<{status:string}>(sql`select status from amo.outsourced_work where id=${id} and operator_id=${p.operatorId}`);const row=q.rows[0];if(!row)throw new DomainError('OUTSOURCE_NOT_FOUND','Outsourced work not found',404);if(!transitionAllowed(OUTSOURCE_TRANSITIONS,row.status as any,b.state as any))throw new DomainError('OUTSOURCE_TRANSITION',`${row.status} cannot transition to ${b.state}`,409);if(['RETURNED','ACCEPTED'].includes(b.state)&&!b.returnReleaseRef)throw new DomainError('OUTSOURCE_RELEASE_REF','Returned outsourced work requires a release/trace reference',422);await this.db.db.execute(sql`update amo.outsourced_work set status=${b.state},return_release_ref=coalesce(${b.returnReleaseRef},return_release_ref),returned_at=case when ${b.state}='RETURNED' then now() else returned_at end,updated_at=now() where id=${id} and operator_id=${p.operatorId}`);await this.auditRecord(p,'maintenance.outsource_state','outsourced_work',id,{from:row.status,to:b.state,returnReleaseRef:b.returnReleaseRef});return {ok:true};}

  async materialKits(p:Principal,workOrderId?:string,wpId?:string){await this.can(p,'read');const cols=sql.raw(`id,work_order_id as "workOrderId",wp_id as "wpId",kit_no as "kitNo",station,status,prepared_by as "preparedBy",prepared_at as "preparedAt",issued_by as "issuedBy",issued_at as "issuedAt",created_at as "createdAt"`);let q;if(workOrderId)q=await this.db.db.execute<Record<string,unknown>>(sql`select ${cols} from amo.material_kits where operator_id=${p.operatorId} and work_order_id=${workOrderId} order by created_at`);else if(wpId)q=await this.db.db.execute<Record<string,unknown>>(sql`select ${cols} from amo.material_kits where operator_id=${p.operatorId} and wp_id=${wpId} order by created_at`);else q=await this.db.db.execute<Record<string,unknown>>(sql`select ${cols} from amo.material_kits where operator_id=${p.operatorId} and status not in ('CLOSED','CANCELLED') order by station,created_at`);const ids=q.rows.map((x:any)=>x.id);const items=ids.length?await this.db.db.execute<Record<string,unknown>>(sql`select id,kit_id as "kitId",part_no as "partNo",description,qty_required as "qtyRequired",qty_picked as "qtyPicked",stock_ref as "stockRef",certificate_ref as "certificateRef",picked_by as "pickedBy",picked_at as "pickedAt" from amo.material_kit_items where operator_id=${p.operatorId} and kit_id in ${sql`(${sql.join(ids.map(x=>sql`${x}`),sql`,`)})`} order by part_no`):{rows:[] as Record<string,unknown>[]};return q.rows.map((k:any)=>({...k,items:items.rows.filter((i:any)=>i.kitId===k.id)}));}
  async createMaterialKit(p:Principal,b:z.infer<typeof materialKitSchema>){await this.can(p,'supervise');const id=randomUUID();await this.db.db.execute(sql`insert into amo.material_kits(id,operator_id,work_order_id,wp_id,kit_no,station,status,created_by) values(${id},${p.operatorId},${b.workOrderId},${b.wpId},${b.kitNo.toUpperCase()},${b.station},'PLANNED',${actorOf(p)})`);await this.auditRecord(p,'maintenance.material_kit_created','material_kit',id,b);return {id};}
  async addMaterialKitItem(p:Principal,kitId:string,b:z.infer<typeof materialKitItemSchema>){await this.can(p,'supervise',kitId);const kit=await this.db.db.execute<{status:string}>(sql`select status from amo.material_kits where id=${kitId} and operator_id=${p.operatorId}`);if(!kit.rows[0])throw new DomainError('MATERIAL_KIT_NOT_FOUND','Material kit not found',404);if(!['PLANNED','PICKING'].includes(kit.rows[0].status))throw new DomainError('MATERIAL_KIT_STATE','Items can only be changed while planning/picking',409);const id=randomUUID();await this.db.db.execute(sql`insert into amo.material_kit_items(id,operator_id,kit_id,part_no,description,qty_required,qty_picked,stock_ref,certificate_ref) values(${id},${p.operatorId},${kitId},${b.partNo.toUpperCase()},${b.description},${b.qtyRequired},0,${b.stockRef},${b.certificateRef})`);await this.auditRecord(p,'maintenance.material_kit_item_added','material_kit_item',id,{kitId,...b});return {id};}
  async pickMaterialKitItem(p:Principal,kitId:string,itemId:string,b:z.infer<typeof materialKitPickSchema>){await this.can(p,'supervise',kitId);const r=await this.db.db.execute<{qty_required:number}>(sql`select qty_required from amo.material_kit_items where id=${itemId} and kit_id=${kitId} and operator_id=${p.operatorId}`);if(!r.rows[0])throw new DomainError('MATERIAL_KIT_ITEM_NOT_FOUND','Material kit item not found',404);if(b.qtyPicked>Number(r.rows[0].qty_required))throw new DomainError('KIT_OVERPICK','Picked quantity exceeds requirement',422);await this.db.db.execute(sql`update amo.material_kit_items set qty_picked=${b.qtyPicked},stock_ref=${b.stockRef},certificate_ref=${b.certificateRef},picked_by=${actorOf(p)},picked_at=now() where id=${itemId} and operator_id=${p.operatorId}`);await this.auditRecord(p,'maintenance.material_kit_item_picked','material_kit_item',itemId,{kitId,...b});return {ok:true};}
  async materialKitState(p:Principal,kitId:string,b:z.infer<typeof materialKitStateSchema>){await this.can(p,'supervise',kitId);const r=await this.db.db.execute<{status:string}>(sql`select status from amo.material_kits where id=${kitId} and operator_id=${p.operatorId}`);const k=r.rows[0];if(!k)throw new DomainError('MATERIAL_KIT_NOT_FOUND','Material kit not found',404);const allowed:Record<string,string[]>={PLANNED:['PICKING','CANCELLED'],PICKING:['READY','CANCELLED'],READY:['ISSUED','PICKING','CANCELLED'],ISSUED:['CLOSED'],CLOSED:[],CANCELLED:[]};if(!allowed[k.status]?.includes(b.state))throw new DomainError('MATERIAL_KIT_TRANSITION',`${k.status} cannot transition to ${b.state}`,409);if(b.state==='READY'){const miss=await this.db.db.execute(sql`select id from amo.material_kit_items where operator_id=${p.operatorId} and kit_id=${kitId} and qty_picked<qty_required limit 1`);if(miss.rows.length)throw new DomainError('MATERIAL_KIT_INCOMPLETE','All required material must be picked before kit readiness',422);}await this.db.db.execute(sql`update amo.material_kits set status=${b.state},prepared_by=case when ${b.state}='READY' then ${actorOf(p)} else prepared_by end,prepared_at=case when ${b.state}='READY' then now() else prepared_at end,issued_by=case when ${b.state}='ISSUED' then ${actorOf(p)} else issued_by end,issued_at=case when ${b.state}='ISSUED' then now() else issued_at end where id=${kitId} and operator_id=${p.operatorId}`);await this.auditRecord(p,'maintenance.material_kit_state','material_kit',kitId,{from:k.status,to:b.state});return {ok:true};}

  async progressReports(p:Principal,workOrderId?:string,wpId?:string){await this.can(p,'read');const r=workOrderId?await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.customer_progress_reports where operator_id=${p.operatorId} and work_order_id=${workOrderId} order by sent_at desc`):wpId?await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.customer_progress_reports where operator_id=${p.operatorId} and wp_id=${wpId} order by sent_at desc`):await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.customer_progress_reports where operator_id=${p.operatorId} order by sent_at desc limit 200`);return r.rows;}
  async addProgressReport(p:Principal,b:z.infer<typeof progressSchema>){await this.can(p,'supervise');const id=randomUUID();await this.db.db.execute(sql`insert into amo.customer_progress_reports(id,operator_id,work_order_id,wp_id,customer_ref,percent_complete,forecast_release,tat_variance_minutes,summary,risks,sent_by) values(${id},${p.operatorId},${b.workOrderId},${b.wpId},${b.customerRef},${b.percentComplete},${b.forecastRelease?new Date(b.forecastRelease):null},${b.tatVarianceMinutes},${b.summary},${JSON.stringify(b.risks)}::jsonb,${actorOf(p)})`);await this.auditRecord(p,'maintenance.customer_progress_sent','customer_progress_report',id,b);return {id};}

  async contracts(p:Principal){await this.can(p,'read');const r=await this.db.db.execute<Record<string,unknown>>(sql`select id,customer_ref as "customerRef",contract_ref as "contractRef",station_scope as "stationScope",aircraft_types as "aircraftTypes",maintenance_levels as "maintenanceLevels",response_sla_minutes as "responseSlaMinutes",tat_sla_hours as "tatSlaHours",rate_card as "rateCard",effective_from as "effectiveFrom",effective_until as "effectiveUntil",active,approved_by as "approvedBy",approved_at as "approvedAt" from amo.maintenance_contracts where operator_id=${p.operatorId} order by active desc,effective_from desc`);return r.rows;}
  async createContract(p:Principal,b:z.infer<typeof contractSchema>){await this.can(p,'supervise');const from=new Date(`${b.effectiveFrom}T00:00:00Z`),until=b.effectiveUntil?new Date(`${b.effectiveUntil}T00:00:00Z`):null;if(until&&until<from)throw new DomainError('CONTRACT_DATES','Contract effective-until precedes effective-from',422);const id=randomUUID();await this.db.transaction(async()=>{await this.db.db.execute(sql`insert into amo.maintenance_contracts(id,operator_id,customer_ref,contract_ref,station_scope,aircraft_types,maintenance_levels,response_sla_minutes,tat_sla_hours,rate_card,effective_from,effective_until,active,approved_by,approved_at) values(${id},${p.operatorId},${b.customerRef},${b.contractRef},${JSON.stringify(b.stationScope.map(x=>x.toUpperCase()))}::jsonb,${JSON.stringify(b.aircraftTypes.map(x=>x.toUpperCase()))}::jsonb,${JSON.stringify(b.maintenanceLevels)}::jsonb,${b.responseSlaMinutes},${b.tatSlaHours},${JSON.stringify(b.rateCard)}::jsonb,${from},${until},true,${actorOf(p)},now())`);await this.auditRecord(p,'maintenance.contract_approved','maintenance_contract',id,b)});return {id};}
  async contractState(p:Principal,id:string,b:z.infer<typeof contractStateSchema>){await this.can(p,'supervise',id);const r=await this.db.db.execute(sql`update amo.maintenance_contracts set active=${b.active} where id=${id} and operator_id=${p.operatorId} returning id`);if(!r.rows[0])throw new DomainError('MAINT_CONTRACT','Maintenance contract not found',404);await this.auditRecord(p,b.active?'maintenance.contract_activated':'maintenance.contract_suspended','maintenance_contract',id,{reason:b.reason});return {ok:true};}

  async floor(p:Principal,wpId:string){await this.can(p,'read',wpId);const prodResult=await this.db.db.execute<Record<string,unknown>>(sql`select * from amo.work_package_production where operator_id=${p.operatorId} and wp_id=${wpId}`);const prod=prodResult.rows[0]??null;const zones=await this.db.db.select().from(wpZones).where(and(eq(wpZones.operatorId,p.operatorId),eq(wpZones.wpId,wpId))).orderBy(asc(wpZones.zone));const panels=await this.db.db.select().from(wpPanels).where(and(eq(wpPanels.operatorId,p.operatorId),eq(wpPanels.wpId,wpId))).orderBy(asc(wpPanels.panel));return {production:prod,zones,panels};}
  async addZone(p:Principal,wpId:string,b:z.infer<typeof zoneSchema>){await this.can(p,'supervise',wpId);const id=randomUUID();await this.db.db.insert(wpZones).values({id,operatorId:p.operatorId,wpId,zone:b.zone,plannedHours:b.plannedHours,actualMinutes:0,status:'NOT_STARTED'});await this.auditRecord(p,'maintenance.zone_added','work_package_zone',id,{wpId,...b});return {id};}
  async zoneState(p:Principal,wpId:string,zone:string,b:z.infer<typeof zoneStateSchema>){await this.can(p,'supervise',wpId);const [zrow]=await this.db.db.select().from(wpZones).where(and(eq(wpZones.operatorId,p.operatorId),eq(wpZones.wpId,wpId),eq(wpZones.zone,zone)));if(!zrow)throw new DomainError('ZONE_NOT_FOUND','Work-package zone not found',404);if(b.state==='CLOSED'){const openPanels=await this.db.db.select().from(wpPanels).where(and(eq(wpPanels.operatorId,p.operatorId),eq(wpPanels.wpId,wpId),eq(wpPanels.zone,zone),sql`${wpPanels.status} <> 'CLOSED'`));if(openPanels.length)throw new DomainError('PANELS_OPEN','Zone cannot close while access panels remain open',422);}await this.db.db.update(wpZones).set({status:b.state,actualMinutes:b.actualMinutes??zrow.actualMinutes}).where(eq(wpZones.id,zrow.id));await this.auditRecord(p,'maintenance.zone_state','work_package_zone',zrow.id,{wpId,zone,from:zrow.status,to:b.state,actualMinutes:b.actualMinutes});return {ok:true};}
  async addPanel(p:Principal,wpId:string,b:z.infer<typeof panelSchema>){await this.can(p,'supervise',wpId);const id=randomUUID();await this.db.db.insert(wpPanels).values({id,operatorId:p.operatorId,wpId,panel:b.panel,zone:b.zone,status:'CLOSED',openedBy:null,openedAt:null,closedBy:null,closedAt:null});await this.auditRecord(p,'maintenance.access_panel_added','work_package_access_panel',id,{wpId,...b});return {id};}
  async panelState(p:Principal,wpId:string,panel:string,b:z.infer<typeof panelStateSchema>){await this.can(p,'supervise',wpId);const [r]=await this.db.db.select().from(wpPanels).where(and(eq(wpPanels.operatorId,p.operatorId),eq(wpPanels.wpId,wpId),eq(wpPanels.panel,panel)));if(!r)throw new DomainError('PANEL_NOT_FOUND','Access panel not found',404);const now=new Date();await this.db.db.update(wpPanels).set({status:b.state,openedBy:b.state==='OPEN'?actorOf(p):r.openedBy,openedAt:b.state==='OPEN'?now:r.openedAt,closedBy:b.state==='CLOSED'?actorOf(p):null,closedAt:b.state==='CLOSED'?now:null}).where(eq(wpPanels.id,r.id));await this.auditRecord(p,'maintenance.access_panel_state','work_package_access_panel',r.id,{wpId,panel,from:r.status,to:b.state});return {ok:true};}
}

